import sys

def main():
    data = sys.stdin.read().split()
    k = int(data[0])
    n = int(data[1])
    p = [int(x) for x in data[2:2 + n]]
    if k >= n // 2:
        ans = sum(max(0, p[i] - p[i - 1]) for i in range(1, n))
    else:
        NEG = -10 ** 18
        buy = [NEG] * (k + 1)
        sell = [0] * (k + 1)
        for x in p:
            for j in range(1, k + 1):
                if sell[j - 1] - x > buy[j]:
                    buy[j] = sell[j - 1] - x
                if buy[j] + x > sell[j]:
                    sell[j] = buy[j] + x
        ans = sell[k]
    print(ans)

